-- Generated by tux-theme ({{theme_name}}): Neovim follows the tuxcraft colour scheme.
-- Each scheme uses its real Neovim theme; anything else (Motif, your own palettes) is built
-- from the palette with mini.base16. Reopen Neovim after `tux-theme set ...`.
local scheme, light = "{{theme}}", ("{{variant}}" == "light")
vim.o.background = light and "light" or "dark"

local themes = {
  gruvbox = { "ellisonleao/gruvbox.nvim", colorscheme = "gruvbox" },
  everforest = { "neanias/everforest-nvim", main = "everforest", colorscheme = "everforest" },
  ["catppuccin-mocha"] = { "catppuccin/nvim", name = "catppuccin", colorscheme = "catppuccin-mocha" },
  ["catppuccin-latte"] = { "catppuccin/nvim", name = "catppuccin", colorscheme = "catppuccin-latte" },
  nord = { "gbprod/nord.nvim", colorscheme = "nord" },
  ["tokyo-night"] = { "folke/tokyonight.nvim", colorscheme = "tokyonight-night" },
  ["rose-pine"] = { "rose-pine/neovim", name = "rose-pine", colorscheme = "rose-pine" },
  kanagawa = { "rebelot/kanagawa.nvim", colorscheme = "kanagawa-wave" },
  dracula = { "Mofiqul/dracula.nvim", colorscheme = "dracula" },
}

local t = themes[scheme]
if t then
  local cs = t.colorscheme
  t.colorscheme, t.lazy, t.priority = nil, false, 1000
  return { t, { "LazyVim/LazyVim", opts = { colorscheme = cs } } }
end

-- Fallback: the tuxcraft palette itself, as a base16 scheme.
return {
  { "nvim-mini/mini.base16", lazy = false, priority = 1000 },
  {
    "LazyVim/LazyVim",
    opts = {
      colorscheme = function()
        require("mini.base16").setup({
          palette = {
            base00 = "{{bg}}", base01 = "{{bg_alt}}", base02 = "{{bg_hl}}", base03 = "{{muted}}",
            base04 = "{{fg_dim}}", base05 = "{{fg}}", base06 = "{{fg}}", base07 = "{{fg}}",
            base08 = "{{red}}", base09 = "{{orange}}", base0A = "{{yellow}}", base0B = "{{green}}",
            base0C = "{{cyan}}", base0D = "{{blue}}", base0E = "{{magenta}}", base0F = "{{orange}}",
          },
          use_cterm = true,
        })
      end,
    },
  },
}
